// Package assets embeds the popcorn icons (generated by tools/genicon).
package assets

import (
	_ "embed"
	"runtime"
)

var (
	//go:embed tray.ico
	trayICO []byte
	//go:embed tray-paused.ico
	trayPausedICO []byte
	//go:embed tray.png
	trayPNG []byte
	//go:embed tray-paused.png
	trayPausedPNG []byte

	//go:embed icon-128.png
	Icon128 []byte
	// Guide is the Tailscale how-to page; {{ICON}} is replaced with Icon128.
	//go:embed guide.html
	Guide []byte
)

// Tray returns the tray icon in the format the OS tray expects (ICO on
// Windows, PNG elsewhere); paused gives the greyed-out variant.
func Tray(paused bool) []byte {
	if runtime.GOOS == "windows" {
		if paused {
			return trayPausedICO
		}
		return trayICO
	}
	if paused {
		return trayPausedPNG
	}
	return trayPNG
}
